<script setup lang="ts">
import { ref, reactive, computed } from 'vue'
import { api, put, items, query, errorText } from '../api'
import { useLoad, today } from '../composables'
import { ElMessage } from 'element-plus'
const rule=ref<any>(null),pendingRule=ref<any>(null),saving=ref(false),calendar=ref<any[]>([]),month=ref(today().slice(0,7)),calendarError=ref(''),calendarLoading=ref(false),calendarDialog=ref(false),formError=ref(''),calendarForm=reactive({date:'',workday:true,note:''})
const form=reactive({startTime:'09:00:00',endTime:'18:00:00',lateGraceMinutes:5,earlyGraceMinutes:5,inWindowStart:'06:00:00',inWindowEnd:'11:59:59',outWindowStart:'12:00:00',outWindowEnd:'23:59:59'})
const fields=[{key:'startTime',label:'上班时间'},{key:'endTime',label:'下班时间'},{key:'inWindowStart',label:'签到窗口开始'},{key:'inWindowEnd',label:'签到窗口结束'},{key:'outWindowStart',label:'签退窗口开始'},{key:'outWindowEnd',label:'签退窗口结束'}] as const
const {loading,error,load}=useLoad(async()=>{const data=await api('/rules');rule.value=data.activeRule;pendingRule.value=data.pendingRule;if(data.pendingRule||data.activeRule){const source=data.pendingRule||data.activeRule;for(const key of Object.keys(form) as (keyof typeof form)[])(form as any)[key]=typeof source[key]==='string'&&source[key].length===5?source[key]+':00':source[key]};await loadCalendar()})
const effective=computed(()=>pendingRule.value?.effectiveDate||pendingRule.value?.effectiveFrom)
async function loadCalendar(){calendarLoading.value=true;calendarError.value='';try{const [y,m]=month.value.split('-').map(Number);const last=new Date(y!,m!,0).getDate();calendar.value=items(await api('/calendar?'+query({from:`${month.value}-01`,to:`${month.value}-${last}`,size:40})))}catch(e){calendarError.value=errorText(e)}finally{calendarLoading.value=false}}
async function save(){saving.value=true;formError.value='';try{await put('/rules',form);ElMessage.success('新规则已保存，从次日开始生效');await load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
function editCalendar(row?:any){Object.assign(calendarForm,{date:row?.date||'',workday:row?.workday??true,note:row?.note||''});formError.value='';calendarDialog.value=true}
async function saveCalendar(){if(!calendarForm.date||calendarForm.date<=today()){formError.value='只能修改未来日期的工作日历';return}saving.value=true;formError.value='';try{await put(`/calendar/${calendarForm.date}`,{workday:calendarForm.workday,note:calendarForm.note});ElMessage.success('工作日历已更新');calendarDialog.value=false;loadCalendar()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
</script>
<template><div class="page-head"><div><h1>规则与日历</h1><p>规则适用于全体员工，修改后次日生效。</p></div></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="pendingRule" :title="`存在待生效规则${effective?'，生效日期：'+effective:'（次日生效）'}。下面的表单展示待生效配置。`" type="info" show-icon :closable="false"/><div class="panel" v-loading="loading"><div class="panel-head"><div><h2>固定日班</h2><p>北京时间 · 默认周一至周五工作</p></div><el-tag type="success">次日生效</el-tag></div><div v-if="rule" class="rule-hint" style="margin-bottom:20px">当前班次：{{rule.startTime}} — {{rule.endTime}} · 迟到宽限 {{rule.lateGraceMinutes}} 分钟 · 早退宽限 {{rule.earlyGraceMinutes}} 分钟</div><el-alert v-if="formError&&!calendarDialog" :title="formError" type="error" :closable="false"/><el-form label-position="top" class="compact-form"><div class="form-grid"><el-form-item v-for="field in fields" :key="field.key" :label="field.label"><el-time-picker v-model="form[field.key]" format="HH:mm:ss" value-format="HH:mm:ss" :clearable="false" style="width:100%"/></el-form-item><el-form-item label="迟到宽限（分钟）"><el-input-number v-model="form.lateGraceMinutes" :min="0" :max="60"/></el-form-item><el-form-item label="早退宽限（分钟）"><el-input-number v-model="form.earlyGraceMinutes" :min="0" :max="60"/></el-form-item></div><el-button type="primary" :loading="saving" @click="save">保存规则</el-button></el-form><p class="footnote">历史考勤沿用当日规则。当前支持固定日班，不含跨夜、轮班和加班计算。</p></div><div class="panel section-gap"><div class="panel-head"><div><h2>工作日历</h2><p>设置未来的调休与假期，其余日期按默认工作周计算</p></div><el-button type="primary" plain @click="editCalendar()">设置日期例外</el-button></div><div class="toolbar"><el-date-picker v-model="month" type="month" value-format="YYYY-MM" :clearable="false" @change="loadCalendar"/></div><el-alert v-if="calendarError" :title="calendarError" type="error" :closable="false"/><el-table :data="calendar" v-loading="calendarLoading" empty-text="当前月份没有日期例外，默认周一至周五为工作日"><el-table-column prop="date" label="日期" width="150"/><el-table-column label="工作日设置" width="160"><template #default="{row}"><el-tag :type="row.workday?'success':'info'">{{row.workday?'工作日':'休息日'}}</el-tag></template></el-table-column><el-table-column prop="note" label="备注" min-width="180"/><el-table-column label="操作" width="110"><template #default="{row}"><el-button text type="primary" :disabled="row.date<=today()" @click="editCalendar(row)">修改</el-button></template></el-table-column></el-table></div><el-dialog v-model="calendarDialog" title="设置未来日期例外" width="470px"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><el-form-item label="日期"><el-date-picker v-model="calendarForm.date" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item label="当日类型"><el-radio-group v-model="calendarForm.workday"><el-radio-button :value="true">工作日</el-radio-button><el-radio-button :value="false">休息日</el-radio-button></el-radio-group></el-form-item><el-form-item label="备注"><el-input v-model="calendarForm.note" maxlength="200" placeholder="例如：国庆调休"/></el-form-item></el-form><template #footer><el-button @click="calendarDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveCalendar">保存日期设置</el-button></template></el-dialog></template>
